function updateGridHeight(){let e=document.querySelectorAll(".blog-basic-grid--container"),t=[e[4],e[5],e[6]];t.forEach(e=>{if(!e)return;let t=e.querySelector(".image-wrapper");if(!t)return;if(window.innerWidth<800){t.style.removeProperty("height"),t.style.removeProperty("padding-bottom");return}let r=t.getBoundingClientRect().width;t.style.setProperty("height",4*r/3+"px","important"),t.style.setProperty("padding-bottom","0","important")})}window.addEventListener("load",updateGridHeight),window.addEventListener("resize",updateGridHeight);
